[{"document_id": "1343190", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1343190", "reference_date": "2026-10-06", "version": "1", "page": 24, "clause": "3.1", "excerpt": "3.1. Os Direitos Creditórios somente poderão ser adquiridos pela Classe caso atendam,  cumulativamente, os seguintes critérios de elegibilidade, a serem checados pela Gestora, na  respectiva Data de Aquisição e Pagamento pela Classe (“Critérios de Elegibilidade”):
(i) ter sido originado de operação de financiamento, representada por uma CCB  devidamente emitida eletronicamente por uma Devedora, em favor da Endossante, e  registrada perante a Entidade Registradora, observado que os Documentos  Comprobatórios serão verificados pela Gestora por amostragem, na forma e prazo  estabelecidos neste Regulamento;
(ii) ser de legítima e exclusiva titularidade da Endossante, livre e desembaraçado  de quaisquer ônus, gravames ou restrições de qualquer natureza;
(iii) ser devido em até 10 (dez) parcelas mensais, sendo que a primeira parcela  deverá ter um prazo máximo de vencimento de até 90 (noventa) dias contados da  respectiva Data de Aquisição e Pagamento;
(iv) serem provenientes de CCB cujo valor de face seja, no mínimo, R$100,00 (cem  reais) e, no máximo, R$ 5.000,00 (cinco mil reais), dado o viés social referente ao  microcrédito refletido na metodologia de investimento sustentável adotada pela  Classe;", "sha256": "7a7233d733e9a1836d62b0f69e10207850853c92d39866e3d34e4a46ccb6f975", "verification": "primary_passage"}]

[{"document_id": "803105", "title": "Instrumento Particular de Alteração do Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=803105", "reference_date": "2024-12-13", "version": "1", "page": 141, "clause": "", "excerpt": "Na qualidade de subscritor de cotas emitidas pelo FARMTECH KEY ACCOUNTS -  FUNDO DE INVESTIMENTO EM DIREITOS CREDITÓRIOS DO AGRONEGÓCIO -  RESPONSABILIDADE LIMITADA (“Fundo” e “Cotas”, respectivamente), inscrito no  CNPJ sob o n° 58.154.011/0001-06, administrado por OLIVEIRA TRUST  DISTRIBUIDORA DE TÍTULOS E VALORES MOBILIÁRIOS S.A., inscrita no CNPJ sob  o nº 36.113.876/0001-91 (“Administrador”), e gerido por FARM INVESTIMENTOS  GESTÃO DE RECURSOS LTDA., inscrita no CNPJ sob o nº 20.043.909/0001-34  (“Gestor”), declaro neste ato o que se segue:
(i) tive acesso ao inteiro teor do regulamento do Fundo e seus anexos e apêndices,  tendo lido e entendido o inteiro teor dos referidos documentos, com relação aos quais  concordo e manifesto, expressamente, minha adesão, irrevogável e irretratável, sem  quaisquer restrições, a todos os seus termos, cláusulas e condições;
